\documentclass[border=10pt]{standalone}
\usepackage[UTF8]{ctex}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,positioning,calc,decorations.pathreplacing}
\usepackage{amsmath}

\begin{document}
\begin{tikzpicture}[
    node distance=1.8cm and 2.5cm,
    block/.style={rectangle, draw=#1, fill=#1!8, rounded corners=3pt, 
        minimum width=2.8cm, minimum height=1.2cm, align=center,
        font=\small\bfseries, line width=1pt},
    arrow/.style={-{Stealth[length=5pt]}, line width=1pt, #1},
    label/.style={font=\scriptsize, #1},
]

% SOC state nodes
\node[block=teal] (soc_t) {$SOC(t)$\\储能荷电状态};
\node[block=teal, right=3.5cm of soc_t] (soc_t1) {$SOC(t+1)$\\下一时段状态};

% Charging path (top)
\node[block=blue!70!black, above=1.5cm of $(soc_t)!0.5!(soc_t1)$] (charge) {充电过程\\$P_{ch}(t) \cdot \eta_{ch}$};

% Discharging path (bottom)
\node[block=red!70!black, below=1.5cm of $(soc_t)!0.5!(soc_t1)$] (discharge) {放电过程\\$P_{dis}(t) / \eta_{dis}$};

% Wind/Solar input
\node[block=orange!80!black, above=1.2cm of charge] (renewable) {风光余电\\$P_{RE}(t) - P_{load}(t)$};

% Load output
\node[block=purple!70!black, below=1.2cm of discharge] (load) {补充负荷\\$P_{load}(t) - P_{RE}(t)$};

% Arrows - main flow
\draw[arrow=teal!70!black] (soc_t) -- node[above, label=black]{状态转移} (soc_t1);
\draw[arrow=blue!70!black] (charge) -| node[near start, above, label=black]{充入} (soc_t1);
